package net.officefloor.hq.app.watch;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.person.Person;
import net.officefloor.plugin.variable.Val;

/** Records a toggle: PERSON_WATCHED or PERSON_UNWATCHED sheet=<id> by=<user> name=<name>. */
public class AuditWatch {
    public void audit(@Val Watching watching, @Val Person person, Audit audit) {
        audit.record((watching.watched() ? "PERSON_WATCHED" : "PERSON_UNWATCHED") + " sheet=" + person.getSheetId()
                + " by=" + watching.user() + " name=" + person.getName());
    }
}
== Notify.java
package net.officefloor.hq.app.watch;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.person.Person;

/** Tells the person's watchers of a claim of theirs settled, approved or re-settled: one line
 *  NOTIFY sheet=<id> by=<user> user=<watcher> person=<name> number=<n> per watcher, in the order they
 *  started watching. */
public final class Notify {
    private Notify() {
    }

    public static void watchers(WatchStore watches, Audit audit, Person person, String by, Object number) {
        for (String watcher : watches.watchers(person.getSheetId(), person.getId())) {
            audit.record("NOTIFY sheet=" + person.getSheetId() + " by=" + by + " user=" + watcher + " person="
                    + person.getName() + " number=" + number);
        }
    }
}
== RespondWithWatches.java
package net.officefloor.hq.app.watch;

import java.time.LocalDate;
import java.util.List;
import net.officefloor.hq.app.history.History;
import net.officefloor.web.ObjectResponse;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestParam;

/** The ids of the people the user watches on the sheet (none for no user); as of a date, those watched at its end. */
public class RespondWithWatches {
    public void respond(@PathVariable("sheetId") String sheetId,
            @RequestParam(name = "user", required = false) String user,
            @RequestParam(name = "asOf", required = false) String asOf, WatchStore watches,
            ObjectResponse<List<Long>> response) {
        LocalDate on = History.date(asOf);
        response.send(user == null || user.isBlank() ? List.of()
                : on == null ? watches.watchedBy(sheetId.trim(), user.trim())
                : watches.watchedByAsOf(sheetId.trim(), user.trim(), on));
    }
}
== ToggleWatch.java
package net.officefloor.hq.app.watch;

import net.officefloor.hq.app.person.Person;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/** Starts the user watching the person, or stops them when they already do. */
public class ToggleWatch {
    public void toggle(@Val WatchRequest request, @Val Person person, WatchStore watches, Out<Watching> toggled) {
        boolean watched = !watches.watches(person.getSheetId(), person.getId(), request.user());
        if (watched) {
            watches.watch(person.getSheetId(), person.getId(), request.user());
        } else {
            watches.unwatch(person.getSheetId(), person.getId(), request.user());
        }
        toggled.set(new Watching(request.user(), watched));
    }
}
== ValidateWatch.java
package net.officefloor.hq.app.watch;

import net.officefloor.hq.app.role.RoleStore;
import net.officefloor.hq.app.sheet.InvalidSheetException;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestBody;

public class ValidateWatch {
    public void validate(@PathVariable("sheetId") String sheetId, @RequestBody WatchRequest request, Out<WatchRequest> body,
            RoleStore roles) throws InvalidSheetException {
        roles.refuseChange(sheetId.trim(), request == null ? null : request.user());
        if (request == null || request.user() == null || request.user().isBlank()) {
            throw new InvalidSheetException("Sign in to watch a person");
        }
        body.set(new WatchRequest(request.user().trim()));
    }
}
