package net.officefloor.hq.app.sheet;

import jakarta.servlet.FilterChain;
import jakarta.servlet.ServletException;
import jakarta.servlet.http.HttpServletRequest;
import jakarta.servlet.http.HttpServletResponse;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Component;
import org.springframework.web.filter.OncePerRequestFilter;

/**
 * Refuses every change made from a screen showing a sheet as of a date: a request to {@code /api/} other than
 * a read, sent with the {@value #HEADER} header (the date the screen shows), answers 400 with the reason, and
 * reaches no endpoint, so it writes nothing to the store or the audit file. The as-of date belongs to the
 * screen; a change sent without it goes through as usual.
 */
@Component
public class AsOfGuard extends OncePerRequestFilter {

    /** The header a screen showing the sheet as of a date sends with each request. */
    public static final String HEADER = "X-As-Of";

    @Override
    protected boolean shouldNotFilter(HttpServletRequest request) {
        return !request.getRequestURI().startsWith("/api/") || "GET".equals(request.getMethod())
                || "HEAD".equals(request.getMethod()) || "OPTIONS".equals(request.getMethod());
    }

    @Override
    protected void doFilterInternal(HttpServletRequest request, HttpServletResponse response, FilterChain chain)
            throws ServletException, IOException {
        String asOf = request.getHeader(HEADER);
        if (asOf == null || asOf.isBlank()) {
            chain.doFilter(request, response);
            return;
        }
        response.setStatus(HttpStatus.BAD_REQUEST.value());
        response.setContentType("text/plain;charset=UTF-8");
        response.getOutputStream().write(("The sheet is shown as of " + asOf.trim() + ": clear the as-of date to change it")
                .getBytes(StandardCharsets.UTF_8));
    }
}
import { useState } from 'react';
import { useQueryClient } from '@tanstack/react-query';
import { AppHeader } from '../../slots/defs/appHeader';
import { useCurrentSheet, useCurrentUser } from '../../session/session';
import { sheetKey, useSheet } from './sheet';

function SheetPicker() {
  const [user] = useCurrentUser();
  const [sheet, setSheet] = useCurrentSheet();
  const [input, setInput] = useState('');
  const queryClient = useQueryClient();
  const loaded = useSheet(sheet);

  if (!user) return null;
  return (
    <form
      data-testid="sheet-form"
      onSubmit={(e) => {
        e.preventDefault();
        const id = input.trim();
        if (!id) return;
        // Loading an id again re-reads it from the store.
        void queryClient.invalidateQueries({ queryKey: sheetKey(id) });
        setSheet(id);
      }}
    >
      <input data-testid="sheet-id-input" placeholder="Sheet id" value={input} onChange={(e) => setInput(e.target.value)} />
      <button type="submit" data-testid="sheet-load">
        Load
      </button>
      {loaded.data && (
        <span>
          {' '}Sheet <strong data-testid="sheet-current-id">{loaded.data.id}</strong>
        </span>
      )}
    </form>
  );
}

export const contribution = AppHeader.fill({ order: 10, Component: SheetPicker });
import { defineSlot } from '../Slot';

/** The shell's header: who is signed in and which sheet is active. */
export const AppHeader = defineSlot('app.header');

