import { useState } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { HttpError, postJson } from '../../api/http';
import { useSubmitOnce } from '../../query/useSubmitOnce';
import { AppHeader } from '../../slots/defs/appHeader';
import { useCurrentSheet, useCurrentUser } from '../../session/session';
import { useSettings } from '../settings/settings';
import { type Sheet, sheetKey, useSheet } from './sheet';

function SheetToday() {
  const [user] = useCurrentUser();
  const [sheet] = useCurrentSheet();
  const loaded = useSheet(sheet);
  const settings = useSettings(sheet);
  const [input, setInput] = useState('');
  const queryClient = useQueryClient();
  const save = useMutation({
    mutationFn: (today: string) =>
      postJson<Sheet>(`/api/sheets/${encodeURIComponent(sheet)}/today`, { today, user }),
    // A new today changes every date decision on the sheet: re-read all of it.
    onSuccess: () => queryClient.invalidateQueries({ queryKey: sheetKey(sheet) }),
  });
  const submit = useSubmitOnce(save);
  const archive = useMutation({
    mutationFn: () => postJson<Sheet>(`/api/sheets/${encodeURIComponent(sheet)}/archive`, { user }),
    onSuccess: (archived) => queryClient.setQueryData(sheetKey(sheet), archived),
  });
  const submitArchive = useSubmitOnce(archive);
  const [cloneTo, setCloneTo] = useState('');
  const clone = useMutation({
    mutationFn: (to: string) =>
      postJson<{ to: string }>(`/api/sheets/${encodeURIComponent(sheet)}/clone`, { to, user }),
  });
  const submitClone = useSubmitOnce(clone);
  // The sheet's one error element: a refused today, archive or clone, whichever was tried last.
  const failed = save.isError ? save.error : archive.isError ? archive.error : clone.isError ? clone.error : null;

  if (!user || !loaded.data) return null;
  return (
    <form
      data-testid="sheet-today-form"
      onSubmit={(e) => {
        e.preventDefault();
        archive.reset();
        clone.reset();
        submit(input.trim());
      }}
    >
      Today <strong data-testid="sheet-today">{loaded.data.today}</strong>{' '}
      <input
        data-testid="sheet-today-input"
        type="date"
        value={input}
        onChange={(e) => {
          setInput(e.target.value);
          save.reset();
          archive.reset();
          clone.reset();
        }}
      />
11:const WAIT = 8000;
12:const LOAD_WAIT = 30000;      // a sign-in, a sheet load or a today change: the whole sheet is re-read
14:const AUDIT_WAIT = 3000;      // how long an audit line may lag the screen
117:  const deadline = Date.now() + WAIT;
136:  throw new Error(`${what}: neither a result nor an error appeared within ${WAIT}ms`);
203:  page.setDefaultTimeout(LOAD_WAIT);     // an element an action needs that never shows fails here, not at the test's limit
207:  await expect(page.getByTestId('current-user')).toHaveText(user, { timeout: LOAD_WAIT });
215:  await expect(page.getByTestId('sheet-current-id')).toHaveText(sheet, { timeout: LOAD_WAIT });
235:  await expect.poll(() => rows(page).count(), { message: 'the throwaway sheet, which has no one on it, is on screen', timeout: LOAD_WAIT }).toBe(0);
249:  const deadline = Date.now() + LOAD_WAIT;
export async function refresh(page: Page): Promise<void> {
  const sheet = (await page.getByTestId('sheet-current-id').textContent() ?? '').trim();
  const before = new Map<string, number>();
  for (const id of await ids(rows(page), 'person-row-')) before.set(id, await claimRows(row(page, id)).count());
  const retired = page.getByTestId('show-retired');
  const showRetiredWas = (await retired.count()) > 0 ? await retired.isChecked() : null;
  const asofWas = await shown(page.getByTestId('sheet-asof'));
